    """Static LexBFS via partition refinement.  Returns the ordering list."""
    n = len(graph)
    if n == 0:
        return []

    # buckets: list of sets of vertices, in queue order
    buckets = [set(range(n))]
    order = []

    while buckets:
        # pop the first non-empty bucket
        while buckets and not buckets[0]:
            buckets.pop(0)
        if not buckets:
            break
        B = buckets.pop(0)
        for v in sorted(B):
            order.append(v)
            # refine every remaining bucket by adjacency to v
            new_buckets = []
            for C in buckets:
                if not C:
                    continue
                Cn = set()
                Cy = set()
                for w in C:
                    if graph[v][w]:
                        Cy.add(w)
                    else:
                        Cn.add(w)
                if Cn:
                    new_buckets.append(Cn)
                if Cy:
                    new_buckets.append(Cy)
            buckets = new_buckets
    return order


